"""副官立绘 SIFT 识别与弹窗行定位。

总览页左侧立绘使用 SIFT 特征匹配识别当前副官；副官弹窗是单页轮播，
每页显示一个副官名与「替换 / 工作中」按钮。本模块只做纯识别与文本
行定位，不执行 UI 点击。
"""

from __future__ import annotations

import enum
from dataclasses import dataclass
from pathlib import Path
from typing import TYPE_CHECKING

import cv2
import numpy as np

from autowsgr.infra.logger import get_logger


if TYPE_CHECKING:
    from autowsgr.vision import OCRResult


_log = get_logger('ui.decisive')

_IMAGE_ROOT = Path(__file__).resolve().parents[2] / 'data' / 'images' / 'decisive'


class InstructorAction(enum.Enum):
    """副官弹窗按钮语义。"""

    REPLACE = 'replace'
    """显示「替换」— 可以切换。"""

    WORKING = 'working'
    """显示「工作中」— 已在岗，关闭即可。"""

    UNKNOWN = 'unknown'
    """未识别到按钮。"""


@dataclass(frozen=True)
class ReplaceTarget:
    """副官弹窗中目标行的动作与点击位置。"""

    action: InstructorAction
    click_position: tuple[float, float] | None


def _normalize(text: str) -> str:
    return ''.join(text.split())


def _row_overlap(
    left: tuple[int, int, int, int] | None,
    right: tuple[int, int, int, int] | None,
) -> bool:
    if left is None or right is None:
        return True
    _, ly1, _, ly2 = left
    _, ry1, _, ry2 = right
    overlap = min(ly2, ry2) - max(ly1, ry1)
    return overlap > 0


def _center_relative(
    bbox: tuple[int, int, int, int],
    screen_width: int,
    screen_height: int,
) -> tuple[float, float]:
    x1, y1, x2, y2 = bbox
    return (
        ((x1 + x2) / 2) / screen_width,
        ((y1 + y2) / 2) / screen_height,
    )


def select_replace_target(
    results: list[OCRResult],
    target_name: str,
    *,
    screen_width: int,
    screen_height: int,
) -> ReplaceTarget | None:
    """从 OCR 结果中定位目标副官行与「替换 / 工作中」按钮。

    纯函数，供副官弹窗和单测共用。
    """
    normalized_target = _normalize(target_name)
    if not normalized_target:
        return None

    target_rows = [
        result
        for result in results
        if normalized_target in _normalize(result.text)
    ]
    if not target_rows:
        return None

    for target in target_rows:
        for result in results:
            text = _normalize(result.text)
            if '工作中' in text:
                if _row_overlap(target.bbox, result.bbox):
                    return ReplaceTarget(InstructorAction.WORKING, None)
            elif '替换' in text and _row_overlap(target.bbox, result.bbox):
                position = (
                    _center_relative(result.bbox, screen_width, screen_height)
                    if result.bbox is not None
                    else None
                )
                return ReplaceTarget(InstructorAction.REPLACE, position)

    return ReplaceTarget(InstructorAction.UNKNOWN, None)


class InstructorMatcher:
    """基于 SIFT 的副官立绘识别器。"""

    def __init__(
        self,
        templates: dict[str, str],
        *,
        root: Path | None = None,
        min_good_matches: int = 50,
        min_ratio: float = 0.20,
        ratio_test: float = 0.7,
    ) -> None:
        self._root = Path(root) if root is not None else _IMAGE_ROOT
        self._templates = dict(templates)
        self._min_good_matches = min_good_matches
        self._min_ratio = min_ratio
        self._ratio_test = ratio_test
        self._sift = cv2.SIFT_create()
        self._matcher = cv2.BFMatcher(cv2.NORM_L2)
        self._descriptors: dict[str, tuple[int, np.ndarray | None]] = {}
        self._load_templates()

    @property
    def names(self) -> list[str]:
        return sorted(self._descriptors)

    def _load_templates(self) -> None:
        for name, filename in self._templates.items():
            path = self._root / filename
            if not path.is_file():
                _log.warning('[副官] 立绘模板缺失: {}', path)
                continue
            image = cv2.imdecode(np.fromfile(str(path), dtype=np.uint8), cv2.IMREAD_COLOR)
            if image is None or image.ndim != 3:
                _log.warning('[副官] 立绘模板不可读: {}', path)
                continue
            gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
            keypoints, descriptors = self._sift.detectAndCompute(gray, None)
            if descriptors is None or len(keypoints) < 2:
                _log.warning('[副官] 立绘模板缺少特征: {}', path)
                continue
            self._descriptors[name] = (len(keypoints), descriptors)
            _log.debug('[副官] 已加载立绘模板: {} ({} 特征)', name, len(keypoints))

    def identify(self, screen: np.ndarray, roi: tuple[float, float, float, float]) -> str | None:
        """识别截图中 ROI 内的副官名；无法匹配返回 ``None``。"""
        if not self._descriptors:
            return None
        height, width = screen.shape[:2]
        x1, y1, x2, y2 = roi
        crop = screen[
            int(y1 * height) : int(y2 * height),
            int(x1 * width) : int(x2 * width),
        ]
        if crop.size == 0:
            return None
        gray = cv2.cvtColor(crop, cv2.COLOR_RGB2GRAY)
        _, query = self._sift.detectAndCompute(gray, None)
        if query is None or len(query) < 2:
            return None

        best: tuple[float, int, str] | None = None
        for name, (template_count, descriptors) in self._descriptors.items():
            if descriptors is None:
                continue
            pairs = self._matcher.knnMatch(descriptors, query, k=2)
            good = sum(
                1
                for pair in pairs
                if len(pair) == 2 and pair[0].distance < self._ratio_test * pair[1].distance
            )
            ratio = good / max(1, template_count)
            if best is None or (good, ratio) > (best[1], best[0]):
                best = (ratio, good, name)

        if best is None:
            return None
        ratio, good, name = best
        if good < self._min_good_matches or ratio < self._min_ratio:
            return None
        _log.debug('[副官] 立绘匹配: {} (good={}, ratio={:.3f})', name, good, ratio)
        return name
